-- pipeline/insert-feed-item
-- Stores one feed entry unless its normalised URL was seen before. Returns a row only when it is new.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = "https://example.com/news/1?utm_source=x"
--   $3 = "https://example.com/news/1"
--   $4 = "Example headline"
--   $5 = null
--   $6 = null
--   $7 = true
--   $8 = "{\"accident\"}"
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

insert into "feed_items" ("id", "outlet_id", "url", "normalized_url", "title", "summary", "published_at", "seen_at", "matched", "matched_terms", "status", "decided_by", "decided_at")
values (default, $1, $2, $3, $4, $5, $6, default, $7, $8, default, default, default)
on conflict ("normalized_url") do nothing
returning "id", "matched";
